-- Create "checkouts" table
CREATE TABLE `checkouts` (`id` uuid NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `checked_out_at` datetime NOT NULL, `due_at` datetime NULL, `returned_at` datetime NULL, `condition_out` text NOT NULL DEFAULT ('unknown'), `condition_in` text NOT NULL DEFAULT ('unknown'), `checkout_note` text NULL, `return_note` text NULL, `checked_out_by` text NULL, `returned_by` text NULL, `group_checkouts` uuid NOT NULL, `item_checkouts` uuid NOT NULL, `person_checkouts` uuid NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `checkouts_groups_checkouts` FOREIGN KEY (`group_checkouts`) REFERENCES `groups` (`id`) ON DELETE CASCADE, CONSTRAINT `checkouts_items_checkouts` FOREIGN KEY (`item_checkouts`) REFERENCES `items` (`id`) ON DELETE CASCADE, CONSTRAINT `checkouts_persons_checkouts` FOREIGN KEY (`person_checkouts`) REFERENCES `persons` (`id`) ON DELETE RESTRICT);
-- Create "persons" table
CREATE TABLE `persons` (`id` uuid NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `name` text NOT NULL, `email` text NULL, `identifier` text NULL, `notes` text NULL, `active` bool NOT NULL DEFAULT (true), `group_people` uuid NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `persons_groups_people` FOREIGN KEY (`group_people`) REFERENCES `groups` (`id`) ON DELETE CASCADE);
